import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"handl Frontend: Custom .handl Syntax — design detail","description":"","frontmatter":{"title":"handl Frontend: Custom `.handl` Syntax — design detail","type":"design","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0003"]},"headers":[],"relativePath":"web/project/design/0003-ac-frontend-custom-syntax.md","filePath":"vendored/web/project/design/0003-ac-frontend-custom-syntax.md"}'),a={name:`web/project/design/0003-ac-frontend-custom-syntax.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-frontend-custom-handl-syntax-—-design-detail" tabindex="-1">handl Frontend: Custom <code>.handl</code> Syntax — design detail <a class="header-anchor" href="#handl-frontend-custom-handl-syntax-—-design-detail" aria-label="Permalink to “handl Frontend: Custom .handl Syntax — design detail”">​</a></h1><p>Moved verbatim from ADR-0003 (ADR-0161 size budget). The ADR carries the rules; this page carries the full record.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>handl documents are currently written in YAML (or JSON, TOML). The <code>Frontend</code> trait (<code>handl-runtime::Frontend</code>) abstracts format parsing — each frontend parses text into <code>NonFunctionValue</code> and the downstream pipeline (field extraction, type checking, typegen, VM) operates on the value, unaware of the source format.</p><p>YAML works but is verbose for handl&#39;s use case. The verbosity comes from JSON Schema boilerplate stacked with handl special keys:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">fields</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  user</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    type</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> object</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    expr</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &#39;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">http.get(&quot;https://api.example.com/users/1&quot;)</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&#39;</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  is_ok</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    type</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> boolean</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    expr</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &#39;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">http.get(&quot;https://api.example.com/health&quot;).ok</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&#39;</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  greet</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    arg</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> true</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    type</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> string</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    expr</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &#39;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">concat(&quot;hello, &quot;, name)</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&#39;</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">functions</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  add</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    params</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">      a</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">        type</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> number</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">      b</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">        type</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> number</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    return</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">      type</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> number</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">    body</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">a + b</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">auth_headers</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  Authorization</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">Bearer \${env.TOKEN}</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">  Accept</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">application/json</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span></span></code></pre></div><p>A 15-field document is ~80 lines in YAML. Most of the volume is repeated <code>type:</code>, <code>expr:</code>, <code>arg:</code>, and <code>params:</code> keys that the parser could infer from a more compact syntax.</p><h3 id="design-goals" tabindex="-1">Design goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to “Design goals”">​</a></h3><ol><li><strong>Less verbose</strong> — computed fields in one line, not three.</li><li><strong>Type inference</strong> — omit <code>type:</code> when the type is obvious from context (expression result, <code>{}</code> body, <code>[]</code> suffix).</li><li><strong>Familiar syntax</strong> — TypeScript-style type annotations (<code>: type</code>), arrow functions (<code>=&gt;</code>), brace objects (<code>{}</code>).</li><li><strong>Zero downstream changes</strong> — the frontend produces the same <code>NonFunctionValue</code> structure the pipeline already consumes.</li><li><strong>No <code>fields:</code> section</strong> — the syntax form itself distinguishes field declarations from data.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>Implement a new frontend crate <code>handl-frontend-handl</code> that parses a purpose-built <code>.handl</code> syntax and implements the <code>Frontend</code> trait.</strong></p><p>The frontend compiles <code>.handl</code> syntax into the same <code>serde_json::Value</code> structure the YAML frontend produces. No changes to field extraction, type checking, typegen, VM, or any downstream crate.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h3><h4 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to “Comments”">​</a></h4><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// Line comment</span></span>
<span class="line"><span>user =&gt; http.get(&quot;https://api.example.com/users/1&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* Block comment</span></span>
<span class="line"><span>   spanning multiple lines */</span></span>
<span class="line"><span>is_ok: boolean =&gt; http.get(&quot;https://api.example.com/health&quot;).ok</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tags: string[]  // inline comment</span></span></code></pre></div><h4 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to “Operators”">​</a></h4><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Maps to</th></tr></thead><tbody><tr><td><code>=&gt;</code></td><td>Computed field (expression)</td><td><code>expr: &quot;...&quot;</code></td></tr><tr><td><code>=</code></td><td>Literal data assignment</td><td>raw value at top level</td></tr><tr><td><code>:</code></td><td>Type annotation</td><td><code>type: &quot;...&quot;</code></td></tr></tbody></table><h4 id="field-declarations" tabindex="-1">Field declarations <a class="header-anchor" href="#field-declarations" aria-label="Permalink to “Field declarations”">​</a></h4><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// Computed, type inferred</span></span>
<span class="line"><span>user =&gt; http.get(&quot;https://api.example.com/users/1&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Computed, type explicit</span></span>
<span class="line"><span>is_ok: boolean =&gt; http.get(&quot;https://api.example.com/health&quot;).ok</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Type-only (no expr, no braces)</span></span>
<span class="line"><span>api_key: string</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Type with array shorthand</span></span>
<span class="line"><span>tags: string[]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Schema via braces — {} is always object, no &quot;object&quot; keyword needed</span></span>
<span class="line"><span>user_full: {</span></span>
<span class="line"><span>  id: string</span></span>
<span class="line"><span>  name: string</span></span>
<span class="line"><span>} =&gt; http.get(&quot;https://api.example.com/users/1&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Schema only (no expr)</span></span>
<span class="line"><span>user_full: {</span></span>
<span class="line"><span>  id: string</span></span>
<span class="line"><span>  name: string</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Array of objects with schema</span></span>
<span class="line"><span>users: {</span></span>
<span class="line"><span>  id: string</span></span>
<span class="line"><span>  name: string</span></span>
<span class="line"><span>}[]</span></span></code></pre></div><h4 id="parameterized-fields-and-functions" tabindex="-1">Parameterized fields and functions <a class="header-anchor" href="#parameterized-fields-and-functions" aria-label="Permalink to “Parameterized fields and functions”">​</a></h4><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// Parameterized computed field (untyped arg)</span></span>
<span class="line"><span>greet(name) =&gt; concat(&quot;hello, &quot;, name)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Parameterized computed field (typed arg + return)</span></span>
<span class="line"><span>greet_typed(name: string): string =&gt; concat(&quot;hello, &quot;, name)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Function with typed params and return</span></span>
<span class="line"><span>add(a: number, b: number): number =&gt; a + b</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### Generics (type parameters)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Type parameters on functions and fields, using angle brackets (TS-style).</span></span>
<span class="line"><span>Bare type parameters only — no constraints in v1.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`handl</span></span>
<span class="line"><span>// Generic function</span></span>
<span class="line"><span>map&amp;lt;T, U&gt;(items: T[], transform: (T) =&gt; U): U[] =&gt; reduce(items, transform, [])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Generic parameterized field</span></span>
<span class="line"><span>first&amp;lt;T&gt;(arg: T): T =&gt; arg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Generic type-only field</span></span>
<span class="line"><span>items&amp;lt;T&gt;: T[]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Multiple type parameters</span></span>
<span class="line"><span>pair&amp;lt;T, U&gt;(first: T, second: U): { first: T, second: U } =&gt; ...</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>.handl</code> syntax</th><th>Output in <code>NonFunctionValue</code></th></tr></thead><tbody><tr><td><code>map&lt;T, U&gt;(items: T[], ...): U[] =&gt; ...</code></td><td><code>functions: {map: {generic: [&quot;T&quot;, &quot;U&quot;], params: {...}, return: {...}, body: &quot;...&quot;}}</code></td></tr><tr><td><code>first&lt;T&gt;(arg: T): T =&gt; arg</code></td><td><code>fields: {first: {generic: [&quot;T&quot;], arg: {type: &quot;T&quot;}, type: &quot;T&quot;, expr: &quot;arg&quot;}}</code></td></tr><tr><td><code>items&lt;T&gt;: T[]</code></td><td><code>fields: {items: {generic: [&quot;T&quot;], type: &quot;array&quot;, items: {type: &quot;T&quot;}}}</code></td></tr></tbody></table><p>The <code>generic:</code> key is a new special key in the canonical dialect. The typechecker treats type parameter names as <code>Type::Unknown</code> (accepts anything). No constraints in v1 — <code>T: comparable</code> syntax is reserved for future use.</p><h4 id="enum-shorthand" tabindex="-1">Enum shorthand <a class="header-anchor" href="#enum-shorthand" aria-label="Permalink to “Enum shorthand”">​</a></h4><p>Union of literal values with <code>|</code> — type inferred from first value.</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// String enum</span></span>
<span class="line"><span>role: &quot;admin&quot; | &quot;user&quot; | &quot;guest&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Number enum</span></span>
<span class="line"><span>priority: 1 | 2 | 3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Boolean enum</span></span>
<span class="line"><span>active: true | false</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// With computed</span></span>
<span class="line"><span>status: &quot;active&quot; | &quot;inactive&quot; | &quot;pending&quot; =&gt; http.get(&quot;...&quot;).status</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// With modifiers</span></span>
<span class="line"><span>inherit role: &quot;admin&quot; | &quot;user&quot; | &quot;guest&quot;</span></span>
<span class="line"><span>lock priority: 1 | 2 | 3</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>.handl</code> syntax</th><th>Output in <code>NonFunctionValue</code></th></tr></thead><tbody><tr><td><code>role: &quot;admin&quot; | &quot;user&quot; | &quot;guest&quot;</code></td><td><code>fields: {role: {type: &quot;string&quot;, enum: [&quot;admin&quot;, &quot;user&quot;, &quot;guest&quot;]}}</code></td></tr><tr><td><code>priority: 1 | 2 | 3</code></td><td><code>fields: {priority: {type: &quot;number&quot;, enum: [1, 2, 3]}}</code></td></tr><tr><td><code>status: &quot;a&quot; | &quot;b&quot; =&gt; http.get(&quot;...&quot;)</code></td><td><code>fields: {status: {type: &quot;string&quot;, enum: [&quot;a&quot;, &quot;b&quot;], expr: &quot;http.get(...)&quot;}}</code></td></tr></tbody></table><p>The frontend infers <code>type</code> from the first enum value. The <code>|</code> appears only in type position (after <code>:</code>), so there is no ambiguity with expression syntax.</p><h4 id="pipe-and-composition-operators" tabindex="-1">Pipe and composition operators <a class="header-anchor" href="#pipe-and-composition-operators" aria-label="Permalink to “Pipe and composition operators”">​</a></h4><p>Three operators for expression-level flow control:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Name</th><th>Direction</th><th>Returns</th><th>Desugars to</th></tr></thead><tbody><tr><td><code>|&gt;</code></td><td>Pipe</td><td>Left-to-right</td><td>Value (immediate)</td><td>Nested calls: <code>x |&gt; f(a)</code> → <code>f(a, x)</code></td></tr><tr><td><code>&gt;&gt;</code></td><td>Flow</td><td>Left-to-right</td><td>Function (deferred)</td><td><code>fp.flow(f, g)</code></td></tr><tr><td><code>&lt;&lt;</code></td><td>Compose</td><td>Right-to-left</td><td>Function (deferred)</td><td><code>fp.compose(f, g)</code></td></tr></tbody></table><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// |&gt; pipe — immediate, left-to-right</span></span>
<span class="line"><span>// data flows through functions, value as last arg</span></span>
<span class="line"><span>names =&gt; users</span></span>
<span class="line"><span>  |&gt; filter((u) =&gt; u.active)</span></span>
<span class="line"><span>  |&gt; map((u) =&gt; u.name)</span></span>
<span class="line"><span>  |&gt; sort(by_priority)</span></span>
<span class="line"><span>// desugars: sort(by_priority, map(fn, filter(fn2, users)))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// &gt;&gt; flow — deferred, left-to-right (reusable pipeline)</span></span>
<span class="line"><span>getActiveNames =&gt; filter((u) =&gt; u.active) &gt;&gt; map((u) =&gt; u.name) &gt;&gt; sort(by_priority)</span></span>
<span class="line"><span>// desugars: fp.flow(filter_fn, map_fn, sort_fn)</span></span>
<span class="line"><span>active =&gt; apply(getActiveNames, users)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// &lt;&lt; compose — deferred, right-to-left (math convention)</span></span>
<span class="line"><span>getActiveNames =&gt; sort(by_priority) &lt;&lt; map((u) =&gt; u.name) &lt;&lt; filter((u) =&gt; u.active)</span></span>
<span class="line"><span>// desugars: fp.compose(sort_fn, map_fn, filter_fn)</span></span>
<span class="line"><span>active =&gt; apply(getActiveNames, users)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// All three produce the same result: sort(filter(map(users)))</span></span></code></pre></div><p><strong>Desugaring rules:</strong></p><ul><li><code>x |&gt; f(args...)</code> → <code>f(args..., x)</code> — pipe inserts value as last argument</li><li><code>x |&gt; f(a) |&gt; g(b)</code> → <code>g(b, f(a, x))</code> — chains nest inside-out</li><li><code>f &gt;&gt; g &gt;&gt; h</code> → <code>fp.flow(f, g, h)</code> — returns a function</li><li><code>f &lt;&lt; g &lt;&lt; h</code> → <code>fp.compose(f, g, h)</code> — returns a function</li></ul><p><strong>Runtime impact:</strong></p><ul><li><code>|&gt;</code> is <strong>zero-cost</strong> — pure frontend desugaring to nested calls, no new runtime function needed.</li><li><code>&gt;&gt;</code> and <code>&lt;&lt;</code> require <code>fp.flow</code> and <code>fp.compose</code> to be added to <code>handl-lib-utils</code>. These functions accept <code>FunctionValue</code> arguments and return a new <code>FunctionValue</code> that chains them.</li></ul><p><strong>No downstream changes to expression parser or typechecker</strong> — the frontend desugars all three operators into existing expression forms (nested function calls and <code>fp.flow</code>/<code>fp.compose</code> calls) before emitting the <code>expr:</code> string.</p><h4 id="null-coalescing-and-optional-chaining" tabindex="-1">Null coalescing and optional chaining <a class="header-anchor" href="#null-coalescing-and-optional-chaining" aria-label="Permalink to “Null coalescing and optional chaining”">​</a></h4><p>Two operators for safe null handling, both pure frontend desugaring:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Name</th><th>Example</th><th>Desugars to</th><th>Runtime change?</th></tr></thead><tbody><tr><td><code>??</code></td><td>Null coalesce</td><td><code>a ?? b</code></td><td><code>fp.default(a, b)</code> / <code>fp.coalesce(...)</code></td><td>No</td></tr><tr><td><code>?.</code></td><td>Optional chain</td><td><code>user?.address?.city</code></td><td><code>fp.default(fp.default(user, {}).address, {}).city</code></td><td>No</td></tr></tbody></table><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// ?? null coalescing</span></span>
<span class="line"><span>name =&gt; user.name ?? &quot;anonymous&quot;</span></span>
<span class="line"><span>timeout =&gt; config.timeout ?? 3000</span></span>
<span class="line"><span>value =&gt; primary ?? fallback ?? &quot;default&quot;</span></span>
<span class="line"><span>// chains desugar to fp.coalesce(primary, fallback, &quot;default&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ?. optional chaining</span></span>
<span class="line"><span>city =&gt; user?.address?.city</span></span>
<span class="line"><span>port =&gt; config?.server?.port ?? 8080</span></span>
<span class="line"><span>email =&gt; user?.contact?.email ?? &quot;no-email&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Combined with pipe operators</span></span>
<span class="line"><span>result =&gt; users</span></span>
<span class="line"><span>  |&gt; filter(active)</span></span>
<span class="line"><span>  |&gt; map((u) =&gt; u?.name ?? &quot;unknown&quot;)</span></span>
<span class="line"><span>  |&gt; sort(by_priority)</span></span></code></pre></div><p><strong>Desugaring rules:</strong></p><ul><li><code>a ?? b</code> → <code>fp.default(a, b)</code></li><li><code>a ?? b ?? c</code> → <code>fp.coalesce(a, b, c)</code></li><li><code>a?.path</code> → <code>fp.default(a, {}).path</code> (access on empty object returns null)</li><li><code>a?.b?.c</code> → <code>fp.default(fp.default(a, {}).b, {}).c</code></li></ul><p>Both operators are <strong>pure frontend desugaring</strong> — no changes to the expression parser, typechecker, or runtime. The frontend emits the desugared <code>fp.default</code>/<code>fp.coalesce</code> calls in the <code>expr:</code> string.</p><h4 id="data-literal-values" tabindex="-1">Data (literal values) <a class="header-anchor" href="#data-literal-values" aria-label="Permalink to “Data (literal values)”">​</a></h4><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// Object data</span></span>
<span class="line"><span>auth_headers = {</span></span>
<span class="line"><span>  Authorization: &quot;Bearer \${env.TOKEN}&quot;</span></span>
<span class="line"><span>  Accept: &quot;application/json&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Scalar data</span></span>
<span class="line"><span>payload_json = &#39;{&quot;name&quot;:&quot;alice&quot;,&quot;email&quot;:&quot;alice@example.com&quot;}&#39;</span></span></code></pre></div><h4 id="modifiers" tabindex="-1">Modifiers <a class="header-anchor" href="#modifiers" aria-label="Permalink to “Modifiers”">​</a></h4><p>Three field-level modifiers, as keyword prefixes:</p><ul><li><code>inherit</code> — value flows down to nested scopes during scoped interpolation (<code>inheritable: true</code> in YAML).</li><li><code>lock</code> — value cannot be overridden in nested scopes (<code>mutable: false</code> in YAML).</li><li><code>spread</code> — field&#39;s object value is spread into parent, field is removed (<code>merge: true</code> in YAML).</li></ul><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>// Single modifier</span></span>
<span class="line"><span>inherit api_key: string</span></span>
<span class="line"><span>lock version: number</span></span>
<span class="line"><span>spread defaults =&gt; http.get(&quot;https://api.example.com/defaults&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// With type + computed</span></span>
<span class="line"><span>inherit timeout: number =&gt; 3000</span></span>
<span class="line"><span>lock name: string =&gt; &quot;handl&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// With schema</span></span>
<span class="line"><span>inherit config: {</span></span>
<span class="line"><span>  host: string</span></span>
<span class="line"><span>  port: number</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>spread base: {</span></span>
<span class="line"><span>  host: string</span></span>
<span class="line"><span>  port: number</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Combined modifiers</span></span>
<span class="line"><span>inherit lock api_key: string</span></span>
<span class="line"><span>spread base: { host: string }</span></span></code></pre></div><h3 id="how-the-parser-distinguishes-fields-from-data" tabindex="-1">How the parser distinguishes fields from data <a class="header-anchor" href="#how-the-parser-distinguishes-fields-from-data" aria-label="Permalink to “How the parser distinguishes fields from data”">​</a></h3><p>No <code>fields:</code> section is needed. The syntax form is the discriminator:</p><table tabindex="0"><thead><tr><th>Syntax form</th><th>Classification</th><th>Goes into</th></tr></thead><tbody><tr><td><code>key =&gt; expr</code></td><td>Computed field</td><td><code>fields</code></td></tr><tr><td><code>key: type =&gt; expr</code></td><td>Typed computed field</td><td><code>fields</code></td></tr><tr><td><code>key: type</code></td><td>Type-only field</td><td><code>fields</code></td></tr><tr><td><code>key: { ... }</code></td><td>Field with schema</td><td><code>fields</code></td></tr><tr><td><code>key(params) =&gt; expr</code></td><td>Parameterized field</td><td><code>fields</code></td></tr><tr><td><code>key = value</code></td><td>Literal data</td><td>top-level data</td></tr><tr><td><code>key: value</code> (inside <code>{}</code>)</td><td>Object property</td><td>part of parent</td></tr></tbody></table><p>The frontend groups all field declarations under the <code>fields</code> key and all <code>fn</code> declarations under the <code>functions</code> key in the output <code>NonFunctionValue</code>. Data stays at top level.</p><h3 id="output-mapping" tabindex="-1">Output mapping <a class="header-anchor" href="#output-mapping" aria-label="Permalink to “Output mapping”">​</a></h3><table tabindex="0"><thead><tr><th><code>.handl</code> syntax</th><th>Output in <code>NonFunctionValue</code></th></tr></thead><tbody><tr><td><code>user =&gt; http.get(...)</code></td><td><code>fields: {user: {expr: &quot;http.get(...)&quot;}}</code></td></tr><tr><td><code>is_ok: boolean =&gt; ...</code></td><td><code>fields: {is_ok: {type: &quot;boolean&quot;, expr: &quot;...&quot;}}</code></td></tr><tr><td><code>api_key: string</code></td><td><code>fields: {api_key: {type: &quot;string&quot;}}</code></td></tr><tr><td><code>tags: string[]</code></td><td><code>fields: {tags: {type: &quot;array&quot;, items: {type: &quot;string&quot;}}}</code></td></tr><tr><td><code>greet(name) =&gt; ...</code></td><td><code>fields: {greet: {arg: true, expr: &quot;...&quot;}}</code></td></tr><tr><td><code>greet_typed(name: string): string =&gt; ...</code></td><td><code>fields: {greet_typed: {arg: {type: &quot;string&quot;}, type: &quot;string&quot;, expr: &quot;...&quot;}}</code></td></tr><tr><td><code>add(a: number, b: number): number =&gt; a + b</code></td><td><code>functions: {add: {params: {a: {type: &quot;number&quot;}, b: {type: &quot;number&quot;}}, return: {type: &quot;number&quot;}, body: &quot;a + b&quot;}}</code></td></tr><tr><td><code>user_full: { id: string } =&gt; ...</code></td><td><code>fields: {user_full: {properties: {id: {type: &quot;string&quot;}}, expr: &quot;...&quot;}}</code></td></tr><tr><td><code>users: { id: string }[]</code></td><td><code>fields: {users: {type: &quot;array&quot;, items: {properties: {id: {type: &quot;string&quot;}}}}}</code></td></tr><tr><td><code>auth_headers = { ... }</code></td><td><code>auth_headers: { ... }</code> (top-level data)</td></tr><tr><td><code>map&lt;T, U&gt;(items: T[], ...): U[] =&gt; ...</code></td><td><code>functions: {map: {generic: [&quot;T&quot;, &quot;U&quot;], params: {...}, return: {...}, body: &quot;...&quot;}}</code></td></tr><tr><td><code>first&lt;T&gt;(arg: T): T =&gt; arg</code></td><td><code>fields: {first: {generic: [&quot;T&quot;], arg: {type: &quot;T&quot;}, type: &quot;T&quot;, expr: &quot;arg&quot;}}</code></td></tr><tr><td><code>items&lt;T&gt;: T[]</code></td><td><code>fields: {items: {generic: [&quot;T&quot;], type: &quot;array&quot;, items: {type: &quot;T&quot;}}}</code></td></tr><tr><td><code>payload_json = &quot;...&quot;</code></td><td><code>payload_json: &quot;...&quot;</code> (top-level data)</td></tr></tbody></table><h3 id="type-inference-rules" tabindex="-1">Type inference rules <a class="header-anchor" href="#type-inference-rules" aria-label="Permalink to “Type inference rules”">​</a></h3><p>The frontend omits <code>type:</code> when the type is obvious:</p><table tabindex="0"><thead><tr><th>Context</th><th>Inferred type</th></tr></thead><tbody><tr><td><code>{ ... }</code> body</td><td><code>object</code> (with <code>properties</code> from body)</td></tr><tr><td><code>[]</code> suffix</td><td><code>array</code> (with <code>items</code> from prefix type)</td></tr><tr><td><code>=&gt; expr</code> only (no type, no braces)</td><td>omitted — typechecker infers from expr</td></tr><tr><td>Empty <code>{}</code></td><td><code>unknown</code> (no type emitted)</td></tr></tbody></table><p>When <code>type:</code> is omitted, the typechecker&#39;s existing <code>Type::Unknown</code> handling applies — it passes silently if the type cannot be inferred (see <code>handl-typecheck-keys/src/expr/check.rs:37-39</code>).</p><h3 id="implementation-plan" tabindex="-1">Implementation plan <a class="header-anchor" href="#implementation-plan" aria-label="Permalink to “Implementation plan”">​</a></h3><ol><li><strong>New crate <code>handl-frontend-handl</code></strong> — implements <code>Frontend</code> trait.</li><li><strong>Parser</strong> — hand-written or <code>pest</code>/<code>nom</code> PEG parser.</li><li><strong>Codegen</strong> — walks AST, emits <code>serde_json::Value</code> in canonical structure (1:1 mapping, no logic).</li><li><strong>Register in <code>frontend_for</code></strong> — add <code>&quot;handl&quot;</code> match arm in <code>handl-frontend/src/lib.rs</code>.</li><li><strong>Source map</strong> — implement <code>parse_with_locations</code> for type error reporting (line/column tracking).</li></ol><h3 id="verbosity-comparison" tabindex="-1">Verbosity comparison <a class="header-anchor" href="#verbosity-comparison" aria-label="Permalink to “Verbosity comparison”">​</a></h3><table tabindex="0"><thead><tr><th>Construct</th><th><code>.handl</code></th><th>YAML</th><th>Reduction</th></tr></thead><tbody><tr><td>Computed field (no type)</td><td>1 line</td><td>3 lines</td><td>67%</td></tr><tr><td>Typed computed field</td><td>1 line</td><td>3 lines</td><td>67%</td></tr><tr><td>Type-only field</td><td>1 line</td><td>2 lines</td><td>50%</td></tr><tr><td>Array shorthand (<code>string[]</code>)</td><td>1 line</td><td>4 lines</td><td>75%</td></tr><tr><td>Parameterized (untyped arg)</td><td>1 line</td><td>4 lines</td><td>75%</td></tr><tr><td>Parameterized (typed arg)</td><td>1 line</td><td>5 lines</td><td>80%</td></tr><tr><td>Function</td><td>1 line</td><td>7 lines</td><td>86%</td></tr><tr><td>Complex field (schema + expr)</td><td>5 lines</td><td>9 lines</td><td>44%</td></tr><tr><td>Data (object)</td><td>4 lines</td><td>3 lines</td><td>-33%</td></tr><tr><td><strong>Full 15-field example</strong></td><td><strong>~25 lines</strong></td><td><strong>~80 lines</strong></td><td><strong>69%</strong></td></tr></tbody></table><p>YAML remains slightly more compact for pure data objects. <code>.handl</code> wins everywhere else, especially for functions and parameterized fields.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p><strong>Positive:</strong></p><ul><li>69% line reduction for typical documents.</li><li>Type inference eliminates redundant <code>type:</code> declarations.</li><li>Brace-based schemas are visually cleaner than nested YAML maps.</li><li>Arrow syntax unifies fields and functions under one mental model.</li><li>Zero downstream changes — same <code>NonFunctionValue</code>, same pipeline.</li><li>Existing YAML/JSON/TOML frontends remain fully supported.</li></ul><p><strong>Negative:</strong></p><ul><li>New syntax to learn — users must understand <code>=&gt;</code> vs <code>=</code> vs <code>:</code>.</li><li>New crate to maintain (parser, codegen, source maps).</li><li>Data objects are slightly more verbose than YAML (<code>key = { ... }</code> vs <code>key: ...</code>).</li><li>String escaping differs from YAML (single quotes for expr strings inside <code>.handl</code> vs YAML&#39;s quoting rules).</li></ul><p><strong>Open questions:</strong></p><ul><li><strong>Modifier syntax.</strong> Resolved — keyword prefixes: <code>inherit</code>, <code>lock</code>, <code>spread</code>. <ul><li><code>inherit</code> → <code>inheritable: true</code> (value flows down to nested scopes)</li><li><code>lock</code> → <code>mutable: false</code> (value cannot be overridden in nested scopes)</li><li><code>spread</code> → <code>merge: true</code> (object value spread into parent, field removed)</li><li>Modifiers can combine: <code>inherit lock api_key: string</code></li></ul></li><li><strong>Enum shorthand.</strong> Resolved — <code>role: &quot;admin&quot; | &quot;user&quot; | &quot;guest&quot;</code> syntax. Type inferred from first literal value. The <code>|</code> appears only in type position (after <code>:</code>), no ambiguity with expressions.</li><li><strong>Generic constraints.</strong> <code>T: comparable</code> syntax (like TypeScript&#39;s <code>T extends Comparable</code>) is reserved for future use. V1 supports bare type parameters only. Constraints would require a named schema/type registry that does not exist yet.</li><li><strong>Pipe/compose runtime.</strong> <code>|&gt;</code> is pure desugar (no runtime change). <code>&gt;&gt;</code> and <code>&lt;&lt;</code> require adding <code>fp.flow</code> and <code>fp.compose</code> to <code>handl-lib-utils</code> — these return chained <code>FunctionValue</code>s. Implementation detail, not a language design question.</li><li><strong>Multi-line expressions.</strong> Resolved — handl is expression-based, not statement-based. <code>{ }</code> in function bodies groups a single expression (e.g. if-expressions), not multiple statements. Long expressions may need line continuation (<code>\\</code> or automatic inside parens) — deferred to implementation.</li><li><strong>Comments.</strong> Resolved — <code>//</code> for line comments, <code>/* */</code> for block comments (TS-consistent).</li></ul><p><strong>Non-goals:</strong></p><ul><li>This frontend does not replace YAML/JSON/TOML — it is an additional option.</li><li>The <code>.handl</code> syntax does not change the language semantics — it is a pure syntactic transformation producing the same <code>NonFunctionValue</code>.</li><li>Custom dialects (different key names) are not addressed here — the <code>.handl</code> frontend targets the canonical dialect.</li></ul>`,74)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};